on conflict (id) do update set home_depot_id=excluded.home_depot_id,type=excluded.type,temp=excluded.temp,status=excluded.status,weight_cap_kg=excluded.weight_cap_kg,volume_cap_m3=excluded.volume_cap_m3,weekly_fuel_quota_l=excluded.weekly_fuel_quota_l,km_per_l=excluded.km_per_l;
